def count_and_say(n):
    if n == 1:
        return '1'
    prev = count_and_say(n - 1)
    count, result, i = 1, '', 0
    while i < len(prev):
        if i + 1 < len(prev) and prev[i] == prev[i + 1]:
            count += 1
        else:
            result += str(count) + prev[i]
            count = 1
        i += 1
    return result

